import { Source } from './source';
import { mapEvent } from './mapper';

export class EventService {
  constructor(private readonly source: Source, private readonly mapper: (value: string) => string = mapEvent) {}

  /**
   * Streams mapped records from a single source lease.
   *
   * The lease is opened on the first iteration and closed exactly once when the
   * stream ends, no matter how it ends: normal exhaustion, consumer break/return,
   * a failed read, a failed mapper or a consumer-injected throw. When closing
   * fails, an original read/mapper/injected exception wins; a close failure is
   * only propagated when there is nothing else to report.
   */
  async *stream(): AsyncGenerator<string> {
    const lease = await this.source.open();
    let failure: { readonly error: unknown } | undefined;
    try {
      for (;;) {
        const value = await lease.read();
        if (value === null) break;
        yield this.mapper(value);
      }
    } catch (error) {
      failure = { error };
    } finally {
      try {
        await lease.close();
      } catch (closeError) {
        failure ??= { error: closeError };
      }
    }
    if (failure !== undefined) {
      throw failure.error;
    }
  }
}
```

