import { Source } from './source';
import { mapEvent } from './mapper';

export class EventService {
  constructor(private readonly source: Source, private readonly mapper: (value: string) => string = mapEvent) {}
  /**
   * Streams mapped records from a single source lease.
   *
   * The lease is only opened once iteration starts (the generator body runs on
   * the first `next()`), and returning or throwing into a never-started
   * generator neither opens nor closes anything. Exactly one read is issued
   * per `next()`; the only read that does not produce a record is the one
   * establishing exhaustion, so nothing is read ahead.
   *
   * However the stream ends — normal exhaustion, consumer break/return, a
   * failed read, a failed mapper or a consumer-injected throw — the opened
   * lease is closed exactly once. If the close also fails, an original read,
   * mapper or injected exception is preserved; a close failure is propagated
   * only when there is no original exception to report.
   */
  async *stream(): AsyncGenerator<string> {
    const lease = await this.source.open();
    let failure: { readonly error: unknown } | undefined;
    try {
      for (;;) {
        const value = await lease.read();
        if (value === null) break;
        yield this.mapper(value);
      }
    } catch (error) {
      failure = { error };
    } finally {
      if (failure === undefined) {
        // No original failure to protect: let a close failure escape so it
        // replaces whatever completion is in flight (exhaustion, break,
        // return or an injected throw).
        await lease.close();
      } else {
        // An original read, mapper or injected failure must win.
        try {
          await lease.close();
        } catch {
          // ignored: the original failure is rethrown below.
        }
      }
    }
    if (failure !== undefined) {
      throw failure.error;
    }
  }
}
