const assert = require('node:assert/strict');
const { EventService } = require('/workspace/.build/service');

function createSource(options = {}) {
  const queue = [...(options.values ?? [])];
  const log = options.log ?? [];
  const state = { opens: 0, reads: 0, closes: 0 };
  const source = {
    open: async () => { state.opens++; log.push('open'); return {
      read: async () => { state.reads++; log.push('read'); if (options.readError) throw options.readError; const v = queue.shift(); return v === undefined ? null : v; },
      close: async () => { state.closes++; log.push('close'); if (options.closeError) throw options.closeError; },
    }; },
  };
  return { source, state, log };
}

(async () => {
  // 1. empty stream
  {
    const { source, state } = createSource({});
    const found = []; for await (const v of new EventService(source).stream()) found.push(v);
    assert.deepEqual(found, []); assert.equal(state.opens + '/' + state.reads + '/' + state.closes, '1/1/1');
    console.log('1 empty stream ok:', '1/1/1');
  }
  // 2. concurrent next() calls: one read per next, ordered
  {
    const { source, state } = createSource({ values: ['a', 'b'] });
    const g = new EventService(source).stream();
    const [r1, r2, r3] = await Promise.all([g.next(), g.next(), g.next()]);
    assert.deepEqual([r1, r2, r3], [{ value: 'A', done: false }, { value: 'B', done: false }, { value: undefined, done: true }]);
    assert.deepEqual([state.opens, state.reads, state.closes], [1, 3, 1]);
    console.log('2 concurrent next ok');
  }
  // 3. return() racing the in-flight first read (non-null result)
  {
    const { source, state, log } = createSource({ values: ['a', 'b'] });
    const g = new EventService(source).stream();
    const p = g.next();
    const rp = g.return();
    const r1 = await p;
    assert.deepEqual(r1, { value: 'A', done: false });
    assert.deepEqual(await rp, { value: undefined, done: true });
    assert.deepEqual([state.opens, state.reads, state.closes], [1, 1, 1]);
    console.log('3 return during read ok, log:', log.join(','));
  }
  // 4. return() racing the initial open()
  {
    const { source, state } = createSource({ values: ['a'] });
    const g = new EventService(source).stream();
    const p = g.next();
    const rp = g.return();
    assert.deepEqual(await p, { value: 'A', done: false });
    assert.deepEqual(await rp, { value: undefined, done: true });
    assert.deepEqual([state.opens, state.reads, state.closes], [1, 1, 1]);
    console.log('4 return during open ok');
  }
  // 5. read rejects while a return() is queued: original error wins, close once
  {
    const readError = new Error('read failed');
    const { source, state } = createSource({ readError });
    const g = new EventService(source).stream();
    const p = g.next().catch(e => 'next:' + e.message);
    const rp = g.return().catch(e => 'return:' + e.message);
    console.log('5 out:', await p, '|', await rp, '| state:', `${state.opens}/${state.reads}/${state.closes}`);
  }
  // 6. mapper throws on 2nd record in for-await: propagates, closes once
  {
    const mapperError = new Error('mapper failed');
    const mapper = (v) => { if (v === 'b') throw mapperError; return v.toUpperCase(); };
    const { source, state } = createSource({ values: ['a', 'b'] });
    try {
      for await (const v of new EventService(source, mapper).stream()) {}
      console.log('6 UNEXPECTED no throw');
    } catch (e) { console.log('6 rejects with:', e.message, '| state:', `${state.opens}/${state.reads}/${state.closes}`); }
  }
  // 7. next() after abrupt completion returns done, no reopen/reclose
  {
    const readError = new Error('read failed');
    const { source, state } = createSource({ readError });
    const g = new EventService(source).stream();
    await g.next().catch(() => {});
    const after = await g.next();
    assert.deepEqual(after, { value: undefined, done: true });
    assert.deepEqual([state.opens, state.reads, state.closes], [1, 1, 1]);
    console.log('7 next-after-throw ok');
  }
  // 8. return() after normal completion: no second close
  {
    const { source, state } = createSource({ values: ['a'] });
    const g = new EventService(source).stream();
    await g.next(); await g.next();
    assert.deepEqual(await g.return(), { value: undefined, done: true });
    assert.equal(state.closes, 1);
    console.log('8 late return ok');
  }
  // 9. throw() racing mapper failure before first suspension: original wins
  {
    const mapperError = new Error('mapper failed');
    const mapper = () => { throw mapperError; };
    const { source, state } = createSource({ values: ['a'] });
    const g = new EventService(source, mapper).stream(); // body not started yet
    const p = g.next().catch(e => 'next:' + e.message);
    const rp = g.return().catch(e => 'return:' + e.message);
    const tp = g.throw(new Error('injected')).catch(e => 'throw:' + e.message);
    console.log('9 out:', await p, '|', await rp, '|', await tp, '| state:', `${state.opens}/${state.reads}/${state.closes}`);
  }
})().then(() => console.log('ALL EDGE PROBES PASSED'), (e) => { console.error('EDGE PROBE FAILED:', e); process.exit(1); });
